@HiltViewModel class AccountDetailViewModel @Inject constructor(private val accountsRepository:AccountRepository,private val searchRepository:SearchRepository):ViewModel(){
 val accounts=accountsRepository.observeAccounts().stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());private val _totals=MutableStateFlow(AccountOperationTotals());val totals=_totals.asStateFlow();private val _metrics=MutableStateFlow(AccountHierarchyMetrics());val metrics=_metrics.asStateFlow();private val _rows=MutableStateFlow<List<FinanceTransaction>>(emptyList());val rows=_rows.asStateFlow();private val _loading=MutableStateFlow(false);val loading=_loading.asStateFlow();private val _error=MutableStateFlow(false);val error=_error.asStateFlow();private val _selected=MutableStateFlow<Set<String>>(emptySet());val selected=_selected.asStateFlow();private var accountId:String="";private var cursor:SearchCursor?=null;private var end=false;private var totalsJob:Job?=null;private var metricsJob:Job?=null;var query by mutableStateOf("");var type by mutableStateOf<TransactionType?>(null);var sort by mutableStateOf(TransactionSort.DATE_DESC);var fromDate by mutableStateOf<String?>(null);var toDate by mutableStateOf<String?>(null)
 fun load(id:String){if(accountId==id)return;accountId=id;totalsJob?.cancel();totalsJob=viewModelScope.launch{accountsRepository.observeTotals(id).collect{_totals.value=it}};metricsJob?.cancel();metricsJob=viewModelScope.launch{accountsRepository.observeHierarchyMetrics(id).collect{_metrics.value=it}};apply()}
 fun apply(){cursor=null;end=false;_rows.value=emptyList();loadMore()}
 fun loadMore(){if(_loading.value||end||accountId.isBlank())return;_loading.value=true;viewModelScope.launch{runCatching{searchRepository.search(TransactionSearchFilter(query,type,accountId,fromDate=fromDate,toDate=toDate,sort=sort),cursor)}.onSuccess{page->_rows.value=(_rows.value+page.items).takeLast(1000);cursor=page.nextCursor;end=page.nextCursor==null}.onFailure{_error.value=true};_loading.value=false}}
 fun toggle(id:String){_selected.value=if(id in _selected.value)_selected.value-id else _selected.value+id}
 fun clearSelection(){_selected.value=emptySet()}
 fun update(account:Account,name:String,type:AccountType,icon:String,color:String,description:String,order:Int,done:()->Unit)=viewModelScope.launch{runCatching{accountsRepository.update(account.id,name,type,icon,color,description,order)}.onSuccess{done()}.onFailure{_error.value=true}}
 fun moveAccount(account:Account,parentId:String?,done:()->Unit)=viewModelScope.launch{runCatching{accountsRepository.move(account.id,parentId)}.onSuccess{done()}.onFailure{_error.value=true}}
 fun archive(account:Account,done:()->Unit)=viewModelScope.launch{runCatching{accountsRepository.setArchived(account.id,!account.isArchived)}.onSuccess{done()}.onFailure{_error.value=true}}
 fun reassign(target:String,done:()->Unit)=viewModelScope.launch{runCatching{accountsRepository.reassignOperations(accountId,target,_selected.value)}.onSuccess{clearSelection();apply();done()}.onFailure{_error.value=true}}
 fun delete(target:String?,done:()->Unit)=viewModelScope.launch{runCatching{accountsRepository.deleteAndReassign(accountId,target)}.onSuccess{done()}.onFailure{_error.value=true}}
 fun clearError(){_error.value=false}
}

