t.id}){transaction->Row(verticalAlignment=Alignment.CenterVertically){Checkbox(transaction.id in selected,{vm.toggle(transaction.id)});Box(Modifier.weight(1f)){AccountTransactionRow(transaction,onEditTransaction)}}};if(loading)item{BudgetLoadingIndicator(Modifier.fillMaxWidth())}else if(rows.isNotEmpty())item{LaunchedEffect(rows.size){vm.loadMore()}}
  item{HorizontalDivider();LazyRow(horizontalArrangement=Arrangement.spacedBy(8.dp)){item{OutlinedButton({edit=true}){Text(stringResource(R.string.account_detail_edit_account))}};item{OutlinedButton({moveAccount=true}){Text(stringResource(R.string.account_detail_move_account))}};item{OutlinedButton({archive=true}){Text(stringResource(if(account.isArchived)R.string.accounts_restore else R.string.accounts_archive))}};item{TextButton({delete=true}){Text(stringResource(R.string.account_detail_delete))}}}}
 }}
 if(edit&&account!=null)AccountEditorDialog(account,{edit=false}){name,type,icon,color,description,order->vm.update(account,name,type,icon,color,description,order){edit=false}}
 if(archive&&account!=null)BudgetConfirmationDialog(stringResource(if(account.isArchived)R.string.accounts_restore_title else R.string.accounts_archive_title),stringResource(if(account.isArchived)R.string.accounts_restore_message else R.string.accounts_archive_message,account.name),{vm.archive(account){archive=false}},{archive=false},confirmText=stringResource(if(account.isArchived)R.string.accounts_restore else R.string.accounts_archive))
