@Composable private fun AccountEditorDialog(value:Account,dismiss:()->Unit,save:(String,AccountType,String,String,String,Int)->Unit){var name by remember{mutableStateOf(value.name)};var type by remember{mutableStateOf(value.type)};var icon by remember{mutableStateOf(value.iconKey)};var color by remember{mutableStateOf(value.colorKey)};var description by remember{mutableStateOf(value.description)};var order by remember{mutableStateOf(value.displayOrder.toString())};AlertDialog(onDismissRequest=dismiss,title={Text(stringResource(R.string.account_detail_edit_account))},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){item{BudgetTextField(name,{name=it},stringResource(R.string.accounts_name))};item{LazyRow{items(AccountType.entries){candidate->FilterChip(type==candidate,{type=candidate},{Text(accountType(candidate))},Modifier.padding(end=4.dp))}}};item{LazyRow{items(listOf("account","home","search")){candidate->FilterChip(icon==candidate,{icon=candidate},{Icon(accountIcon(candidate),contentDescription=iconLabel(candidate))},Modifier.padding(end=4.dp))}}};item{LazyRow{items(listOf("primary","green","orange","blue")){candidate->val label=colorLabel(candidate);FilterChip(color==candidate,{color=candidate},{Box(Modifier.size(24.dp).background(accountColor(candidate),CircleShape).semantics{contentDescription=label})},Modifier.padding(end=4.dp))}}};item{BudgetTextField(description,{if(it.length<=120)description=it},stringResource(R.string.account_detail_description))};item{BudgetTextField(order,{order=it.filter(Char::isDigit)},stringResource(R.string.account_detail_order))}}},confirmButton={TextButton({save(name.trim(),type,icon,color,description,order.toIntOrNull()?:0)},enabled=name.isNotBlank()&&order.toIntOrNull()!=null){Text(stringResource(R.string.account_detail_save))}},dismissButton={TextButton(dismiss){Text(stringResource(R.string.account_detail_cancel))}})}
