@Composable private fun quickLabel(type:TransactionType)=stringResource(when(type){TransactionType.EXPENSE->R.string.account_detail_add_expense;TransactionType.INCOME->R.string.account_detail_add_income;TransactionType.TRANSFER->R.string.account_detail_add_transfer})
@Composable private fun typeLabel(type:TransactionType)=stringResource(when(type){TransactionType.EXPENSE->R.string.account_detail_expense;TransactionType.INCOME->R.string.account_detail_income_type;TransactionType.TRANSFER->R.string.account_detail_transfer})
@Composable private fun sortLabel(sort:TransactionSort)=stringResource(when(sort){TransactionSort.DATE_DESC->R.string.account_detail_date_desc;TransactionSort.DATE_ASC->R.string.account_detail_date_asc;TransactionSort.AMOUNT_DESC->R.string.account_detail_amount_desc;TransactionSort.AMOUNT_ASC->R.string.account_detail_amount_asc})
@Composable private fun accountType(type:AccountType)=stringResource(when(type){AccountType.CASH->R.string.account_type_cash;AccountType.BANK->R.string.account_type_bank;AccountType.SAVINGS->R.string.account_type_savings;AccountType.CARD->R.string.account_type_card;AccountType.OTHER->R.string.account_type_other})
private fun accountIcon(key:String)=when(key){"home"->BudgetIcons.Home;"search"->BudgetIcons.Search;else->BudgetIcons.Account}
private fun accountColor(key:String)=when(key){"green"->Color(0xFF2E7D32);"orange"->Color(0xFFEF6C00);"blue"->Color(0xFF1565C0);else->Color(0xFF386A54)}
@Composable private fun iconLabel(key:String)=stringResource(when(key){"home"->R.string.account_detail_icon_home;"search"->R.string.account_detail_icon_search;else->R.string.account_detail_icon_account})
@Composable private fun colorLabel(key:String)=stringResource(when(key){"green"->R.string.account_detail_color_green;"orange"->R.string.account_detail_color_orange;"blue"->R.string.account_detail_color_blue;else->R.string.account_detail_color_primary})
